B.aw_=s(["Jugamos f\xfatbol.","Ch\xfang t\xf4i ch\u01a1i b\xf3ng \u0111\xe1."],t.s)
B.aLM=s(["Hoy es mi cumplea\xf1os.","H\xf4m nay l\xe0 sinh nh\u1eadt t\xf4i."],t.s)
B.acV=s(["El panda gigante es lindo.","G\u1ea5u tr\xfac l\u1edbn d\u1ec5 th\u01b0\u01a1ng."],t.s)
B.a3u=s(["El conejo blanco salta y salta.","Th\u1ecf tr\u1eafng nh\u1ea3y tung t\u0103ng."],t.s)
B.Ls=s(["Al oso polar no le da fr\xedo.","G\u1ea5u B\u1eafc C\u1ef1c kh\xf4ng s\u1ee3 l\u1ea1nh."],t.s)
B.a7b=s(["El b\xfaho no duerme de noche.","C\xfa m\xe8o kh\xf4ng ng\u1ee7 v\xe0o ban \u0111\xeam."],t.s)
B.DZ=s(["La luci\xe9rnaga brilla.","\u0110om \u0111\xf3m ph\xe1t s\xe1ng."],t.s)
B.avh=s(["La oruga se convierte en mariposa.","S\xe2u b\u01b0\u1edbm h\xf3a th\xe0nh b\u01b0\u1edbm."],t.s)
B.a0m=s(["El p\xe1jaro carpintero picotea el \xe1rbol.","Chim g\xf5 ki\u1ebfn m\u1ed5 v\xe0o c\xe2y."],t.s)
